import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    m = re.match(r"([A-Z]+)(\d+)", ref)
    letters = m.group(1)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1  # 0-based column

def row_idx(ref):
    return int(re.match(r"[A-Z]+(\d+)", ref).group(1)) - 1

with zipfile.ZipFile("budget.xlsx") as z:
    names = z.namelist()
    print("Files in archive:", names)

    shared = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)

    wb_root = ET.fromstring(z.read("xl/workbook.xml"))
    sheet_names = [s.get("name") for s in wb_root.findall(".//m:sheet", NS)]
    print("Sheets:", sheet_names)

    rels_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {}
    for rel in rels_root.findall("{http://schemas.openxmlformats.org/package/2006/relationships}Relationship"):
        rel_map[rel.get("Id")] = rel.get("Target")

    for sheet_el in wb_root.findall(".//m:sheet", NS):
        rid = sheet_el.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        target = rel_map[rid]
        if not target.startswith("xl/"):
            target = "xl/" + target
        path = target.replace("/xl/", "/xl/") if target.startswith("xl/") else target
        if not path.startswith("xl/"):
            path = "xl/" + path
        sheet_root = ET.fromstring(z.read(path))
        print(f"\n=== Sheet: {sheet_el.get('name')} ({path}) ===")
        for row in sheet_root.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row"):
            for c in row.findall("m:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("m:v", NS)
                if v is None:
                    val = None
                else:
                    raw = v.text
                    if t == "s":
                        val = shared[int(raw)]
                    elif t == "str":
                        val = raw
                    else:
                        val = raw
                print(f"{ref}: {val!r} (type={t})")

